    /// SPGP: flag an assignment to a global or persistent variable inside an
    /// `spmd` block, substituting the variable name for VAR_NAME.
    ///
    /// A `global`/`persistent` declaration alone does not fire; only an
    /// assignment to such a variable inside the spmd body does.
    pub(crate) fn check_spmd_gp_assignment(
        &self,
        root: tree_sitter::Node,
        source: &str,
        symbol_table: &SymbolTable,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        let mut gp_names: HashSet<String> = HashSet::new();
        for scope in &symbol_table.scopes {
            for def in &scope.defs {
                if matches!(def.kind, DefKind::Global | DefKind::Persistent) {
                    gp_names.insert(def.name.clone());
                }
            }
        }
        if gp_names.is_empty() {
            return;
        }
        self.spmd_gp_assignment_dfs(root, source, &gp_names, false, diagnostics);
    }

    /// DFS helper for [`Self::check_spmd_gp_assignment`].
    fn spmd_gp_assignment_dfs(
        &self,
        node: tree_sitter::Node,
        source: &str,
        gp_names: &HashSet<String>,
        in_spmd: bool,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        match node.kind() {
            "spmd_statement" => {
                let mut cursor = node.walk();
                for child in node.children(&mut cursor) {
                    self.spmd_gp_assignment_dfs(child, source, gp_names, true, diagnostics);
                }
                return;
            }
            "function_definition" => {
                // Global/persistent scoping does not cross function boundaries;
                // do not descend into nested/local function bodies.
                return;
